  for (const el of all) { if (!vis(el)) continue; if (el.closest('.amb,.deck-nav,.deck-foot,.ph,.art,.qmark,.backdrop,.fx-aurora,.g-layer')) continue; const r = el.getBoundingClientRect(); const pad = 2; if (r.left < sr.left - pad || r.right > sr.right + pad || r.top < sr.top - pad || r.bottom > sr.bottom + pad) { stats.outside++; if (stats.outside <= 5) issues.push({ sev: 'error', code: 'OUTSIDE_STAGE', el: desc(el), box: [Math.round((r.left - sr.left)/s), Math.round((r.top - sr.top)/s), Math.round(r.width/s), Math.round(r.height/s)] }); } }
  // 2) overflow (scrollable content clipped) & text clipping
  // text-aware: clipped overflow that only involves decorative (absolute, text-less) children is a 'nit', not an error
  function textClipped(el) { const er = el.getBoundingClientRect(); const w = document.createTreeWalker(el, NodeFilter.SHOW_TEXT); let t; while ((t = w.nextNode())) { if (!t.textContent.trim()) continue; const p = t.parentElement; if (!p || !vis(p)) continue; const r = p.getBoundingClientRect(); if (r.right > er.right + 2 || r.bottom > er.bottom + 2 || r.left < er.left - 2 || r.top < er.top - 2) return true; } return false; }
  for (const el of all) { if (!vis(el)) continue; if (el.hasAttribute('data-allow-scroll') || el.closest('[data-allow-scroll],.amb,.ph,.art,.dev,.backdrop,.fx-aurora')) continue; const tb = el.getBoundingClientRect(); if (tb.width < 30 * s && tb.height < 30 * s) continue; /* tiny decorative elements (dots, pulses) */ const cs = getComputedStyle(el); if (el.scrollHeight - el.clientHeight > 4 && el.clientHeight > 0 && (cs.overflowY === 'hidden' || cs.overflowY === 'auto' || cs.overflowY === 'scroll' || el.classList.contains('stage'))) { if (!textClipped(el) && !el.classList.contains('stage')) { issues.push({ sev: 'nit', code: 'OVERFLOW_Y_DECOR', el: desc(el), extra: Math.round((el.scrollHeight - el.clientHeight)/s) }); continue; } stats.overflow++; if (stats.overflow <= 6) issues.push({ sev: 'error', code: 'OVERFLOW_Y', el: desc(el), extra: Math.round((el.scrollHeight - el.clientHeight)/s), box: boxOf(el), text: txt(el), parent: desc(el.parentElement) + ' ' + Math.round(el.parentElement.getBoundingClientRect().width/s) + 'px' }); } if (el.scrollWidth - el.clientWidth > 4 && el.clientWidth > 0 && (cs.overflowX === 'hidden' || cs.whiteSpace === 'nowrap' || cs.textOverflow === 'ellipsis')) { if (cs.overflowX === 'hidden' && cs.whiteSpace !== 'nowrap' && cs.textOverflow !== 'ellipsis' && !textClipped(el)) { issues.push({ sev: 'nit', code: 'OVERFLOW_X_DECOR', el: desc(el), extra: Math.round((el.scrollWidth - el.clientWidth)/s) }); continue; } stats.overflow++; if (stats.overflow <= 6) issues.push({ sev: 'error', code: 'OVERFLOW_X', el: desc(el), extra: Math.round((el.scrollWidth - el.clientWidth)/s), box: boxOf(el), text: txt(el), parent: desc(el.parentElement) + ' ' + Math.round(el.parentElement.getBoundingClientRect().width/s) + 'px' }); } }
  // 3) min font size (text-bearing elements)
  const walker = document.createTreeWalker(stage, NodeFilter.SHOW_TEXT);
  let tn; while ((tn = walker.nextNode())) { if (!tn.textContent.trim()) continue; const el = tn.parentElement; if (!el || !vis(el) || el.closest('svg,.deck-foot,.source,.topbar,.art .lab,.no,.bd,.num,.hs,.url,.tag,.ghost,.bar,.credit,.sec-rail')) continue; stats.textNodes++; const fs = parseFloat(getComputedStyle(el).fontSize) / s; if (fs < stats.minFont) stats.minFont = fs; if (fs < 14) issues.push({ sev: fs < 12.5 ? 'error' : 'warn', code: 'SMALL_FONT', el: desc(el), extra: Math.round(fs*10)/10, text: tn.textContent.trim().slice(0, 30) }); }
